    // Socket.IO can deliver the same entry the REST refresh already returned.
    const key = `${entry.ts || ''}|${entry.actor || ''}|${entry.action || ''}|${entry.url || ''}`
    if (current.some(item => `${item.ts || ''}|${item.actor || ''}|${item.action || ''}|${item.url || ''}` === key)) {
