    }
  },

  setDesktopSizes(state, presets) {
    state.desktopSizes = Array.isArray(presets) && presets.length ? presets : null
  },

  // ── Grid view ───────────────────────────────────────────────────────────

  setViewMode(state, mode) {
    state.viewMode = mode === 'grid' ? 'grid' : 'single'
